/* ---- drawing helpers for this lesson (prefixed OF_ so nothing clashes with the engine) ---- */
const OF_F='font-family="Nunito Sans, sans-serif"';
const OF_T=(x,y,t,o={})=>`<text x="${(+x).toFixed(1)}" y="${(+y).toFixed(1)}" ${OF_F} font-size="${o.fs||24}" font-weight="${o.fw||600}" text-anchor="${o.a||'start'}" fill="${o.fill||'#18213A'}"${o.ex?' '+o.ex:''}>${t}</text>`;
const OF_L=(x1,y1,x2,y2,col='#5C6577',w=2,ex='')=>`<line x1="${(+x1).toFixed(1)}" y1="${(+y1).toFixed(1)}" x2="${(+x2).toFixed(1)}" y2="${(+y2).toFixed(1)}" stroke="${col}" stroke-width="${w}" stroke-linecap="round" ${ex}/>`;
const OF_box=(x,y,w,h,o={})=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${o.r??14}" fill="${o.fill||'#FFFFFF'}" stroke="${o.st||'#CED4DA'}" stroke-width="${o.sw||2}"${o.ex?' '+o.ex:''}/>`;
const OF_arrow=(x1,y1,x2,y2,col='#18213A',w=3)=>{const a=Math.atan2(y2-y1,x2-x1),h=14;return OF_L(x1,y1,x2-h*.6*Math.cos(a),y2-h*.6*Math.sin(a),col,w)+`<polygon points="${x2.toFixed(1)},${y2.toFixed(1)} ${(x2-h*Math.cos(a)+h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)-h*.5*Math.cos(a)).toFixed(1)} ${(x2-h*Math.cos(a)-h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)+h*.5*Math.cos(a)).toFixed(1)}" fill="${col}"/>`};
const OF_R=d=>d*Math.PI/180, OF_D=r=>r*180/Math.PI;
const OF_GREY='#5C6577', OF_CORE='#DBE4FF', OF_CLAD='#F1F3F5';
/* the book's numbers, computed once */
const OF_NA=Math.sqrt(1.48*1.48-1.46*1.46);                 // 0.2425
const OF_TA=OF_D(Math.asin(OF_NA));                          // 14.03°
const OF_TAS=OF_D(Math.asin(OF_NA/Math.cos(OF_R(45))));      // 20.06°
const OF_TBAD=OF_D(Math.asin(1.48-1.46));                    // 1.15°: the cone of the wrong NA = n1 − n2
/* slab of the second worked example: d = 5 µm, n1 = 1.50, n2 = 1.48, λ = 1.3 µm; effective indices from the eigenvalue equations */
const OF_K0=2*Math.PI/1.3, OF_NE=[1.4968989,1.4882333];
const OF_KAP=OF_NE.map(n=>OF_K0*Math.sqrt(1.5*1.5-n*n)), OF_GAM=OF_NE.map(n=>OF_K0*Math.sqrt(n*n-1.48*1.48));
/* field E(x) of TE0 (even) and TE1 (odd), x in µm, normalised to peak 1 */
const OF_E=(m,x)=>{const k=OF_KAP[m],gm=OF_GAM[m],h=2.5,ax=Math.abs(x);
 if(m===0)return ax<=h?Math.cos(k*x):Math.cos(k*h)*Math.exp(-gm*(ax-h));
 return ax<=h?Math.sin(k*x):Math.sign(x)*Math.sin(k*h)*Math.exp(-gm*(ax-h))};
/* a field curve drawn the book's way: x upwards (yc centre, ky px per µm), E to the right (x0 zero line, A px amplitude) */
const OF_mode=(m,x0,yc,ky,A,xr,col,w=4)=>{let p=[];for(let i=0;i<=160;i++){const x=-xr+2*xr*i/160;p.push((x0+A*OF_E(m,x)).toFixed(1)+','+(yc-ky*x).toFixed(1))}
 return OF_L(x0,yc-ky*xr,x0,yc+ky*xr,'#ADB5BD',2,'stroke-dasharray="6 5"')+`<polyline points="${p.join(' ')}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linejoin="round"/>`};
/* slab bands: core of half-thickness hc (px) about yc, claddings out to yr */
const OF_slab=(x0,x1,yc,hc,yr)=>`<rect x="${x0}" y="${yc-yr}" width="${x1-x0}" height="${yr-hc}" fill="${OF_CLAD}"/><rect x="${x0}" y="${yc+hc}" width="${x1-x0}" height="${yr-hc}" fill="${OF_CLAD}"/><rect x="${x0}" y="${yc-hc}" width="${x1-x0}" height="${2*hc}" fill="${OF_CORE}" stroke="${BLU}" stroke-width="2"/>`;
/* a fiber side-on and its acceptance cone (half-angle th) with the apex at the end face (ex,yc) */
const OF_fiber=(x0,x1,yc,hc,cw)=>`<rect x="${x0}" y="${yc-hc-cw}" width="${x1-x0}" height="${cw}" fill="${OF_CLAD}" stroke="#ADB5BD" stroke-width="2"/><rect x="${x0}" y="${yc+hc}" width="${x1-x0}" height="${cw}" fill="${OF_CLAD}" stroke="#ADB5BD" stroke-width="2"/><rect x="${x0}" y="${yc-hc}" width="${x1-x0}" height="${2*hc}" fill="${OF_CORE}" stroke="${BLU}" stroke-width="2"/>`+OF_L(x0,yc-hc-cw,x0,yc+hc+cw,'#18213A',4);
const OF_cone=(ex,yc,L,th,col,op=.2)=>{const dx=L*Math.cos(OF_R(th)),dy=L*Math.sin(OF_R(th));return `<polygon points="${ex},${yc} ${(ex-dx).toFixed(1)},${(yc-dy).toFixed(1)} ${(ex-dx).toFixed(1)},${(yc+dy).toFixed(1)}" fill="${col}" fill-opacity="${op}" stroke="${col}" stroke-width="3" stroke-linejoin="round"/>`};
/* the fiber end-on: cladding ring, core, axis dot */
const OF_end=(cx,cy,r)=>`<circle cx="${cx}" cy="${cy}" r="${(r*1.22).toFixed(1)}" fill="${OF_CLAD}" stroke="#ADB5BD" stroke-width="2"/><circle cx="${cx}" cy="${cy}" r="${r}" fill="${OF_CORE}" stroke="${BLU}" stroke-width="3"/><circle cx="${cx}" cy="${cy}" r="5" fill="#18213A"/>`;
/* a skew ray end-on: chords at angle gam (deg) to the radius, starting at angle a0 */
const OF_skew=(cx,cy,r,gam,col,w=4,a0=-90)=>{const st=180-2*gam;let p=[];for(let i=0;i<=360/st+0.01;i++){const a=OF_R(a0+i*st);p.push((cx+r*Math.cos(a)).toFixed(1)+','+(cy+r*Math.sin(a)).toFixed(1))}
 return `<polyline points="${p.join(' ')}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linejoin="round"/>`};
/* the V axis of the slab: 0 to 7.4, x0 px at V = 0, kx px per unit */
const OF_vaxis=(x0,kx,y)=>OF_L(x0,y,x0+kx*7.4,y,'#18213A',3)+[[0,'0'],[Math.PI,'π'],[2*Math.PI,'2π']].map(([v,l])=>OF_L(x0+kx*v,y-10,x0+kx*v,y+10,'#18213A',3)+OF_T(x0+kx*v,y+40,l,{fs:24,fw:800,a:'middle',fill:'#18213A'})).join('')+OF_T(x0+kx*7.4,y-16,'V',{fs:24,fw:800,a:'end',fill:OF_GREY});

